B06_IDS = ["LR3-002","LR3-004","LR3-006","LR3-008","LR3-010","LR3-101","LR3-104","LR3-107","LR3-110","LR3-112","LR3-114","LR3-116","LY-001","LY-002","LY-003","LY-004","LY-005","LY-006","LY-007","LY-008"]
