# final self-check: re-read each written file exactly by id list
ALL = B04_IDS + B05_IDS + B06_IDS
assert len(ALL) == 60 and len(set(ALL)) == 60
cm = ru = di = 0
for cid in ALL:
    d = json.loads((OUT/f"{cid}.json").read_text(encoding="utf-8"))
    assert d["case_id"] == cid and d["prediction_text"] and d["basis"] and isinstance(d["confidence"], float)
    t = d["trigger"]; assert set(t) == {"changed_main","reserve_used","disputed","reason"}
    cm += bool(t["changed_main"]); ru += bool(t["reserve_used"]); di += bool(t["disputed"])
print("TOTAL", len(ALL), "changed_main", cm, "reserve_used", ru, "disputed", di)
